items.solution_code:
def validate_login(username, password, users=None, passwords=None):
    if users is None:
        users = {}
    if passwords is None:
        passwords = {}
    if username == '' and password == '':
        print('Both empty')
    else:
        if username in users and password in passwords:
            return True
        else:
            return False

